create extension if not exists pgcrypto;
create type public.account_role as enum ('buyer','seller');
create type public.request_status as enum ('open','in_progress','completed','cancelled');
create type public.offer_status as enum ('pending','accepted','rejected','withdrawn');
create type public.transaction_status as enum ('pending','in_progress','completed','refunded');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role public.account_role not null,bio text default '',avatar_url text,created_at timestamptz default now());
create table public.requests(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references public.profiles(id),title text not null check(length(title) between 5 and 120),description text not null,category text not null,budget numeric(12,2) not null check(budget>0),deadline date,image_urls text[] not null default '{}',status public.request_status not null default 'open',created_at timestamptz default now());
create table public.offers(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.requests(id) on delete cascade,seller_id uuid not null references public.profiles(id),price numeric(12,2) not null check(price>0),delivery_days int not null check(delivery_days>0),message text not null,status public.offer_status not null default 'pending',created_at timestamptz default now(),unique(request_id,seller_id));
create table public.messages(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.requests(id) on delete cascade,sender_id uuid not null references public.profiles(id),recipient_id uuid not null references public.profiles(id),body text not null check(length(body) between 1 and 5000),created_at timestamptz default now());
create table public.transactions(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.requests(id),offer_id uuid not null unique references public.offers(id),buyer_id uuid not null references public.profiles(id),seller_id uuid not null references public.profiles(id),amount numeric(12,2) not null check(amount>0),commission_rate numeric(5,4) not null default .0700,commission_amount numeric(12,2) generated always as (round(amount*commission_rate,2)) stored,status public.transaction_status not null default 'pending',payment_reference text,completed_at timestamptz,created_at timestamptz default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references public.transactions(id),reviewer_id uuid not null references public.profiles(id),reviewee_id uuid not null references public.profiles(id),rating int not null check(rating between 1 and 5),comment text default '',created_at timestamptz default now(),unique(transaction_id,reviewer_id));
create index requests_status_created_idx on public.requests(status,created_at desc);
create index requests_category_idx on public.requests(category);
create index offers_request_idx on public.offers(request_id,created_at desc);
create index messages_participants_idx on public.messages(sender_id,recipient_id,created_at desc);
create index transactions_participants_idx on public.transactions(buyer_id,seller_id,status);
alter table public.profiles enable row level security; alter table public.requests enable row level security; alter table public.offers enable row level security; alter table public.messages enable row level security; alter table public.transactions enable row level security; alter table public.reviews enable row level security;
create policy "Profiles public read" on public.profiles for select using(true);
create policy "Own profile insert" on public.profiles for insert to authenticated with check(id=(select auth.uid()));
create policy "Own profile update" on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy "Open requests public read" on public.requests for select using(status='open' or buyer_id=(select auth.uid()));
create policy "Buyer creates request" on public.requests for insert to authenticated with check(buyer_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='buyer'));
create policy "Buyer updates request" on public.requests for update to authenticated using(buyer_id=(select auth.uid())) with check(buyer_id=(select auth.uid()));
create policy "Offer participants read" on public.offers for select to authenticated using(seller_id=(select auth.uid()) or exists(select 1 from public.requests r where r.id=request_id and r.buyer_id=(select auth.uid())));
create policy "Seller submits offer" on public.offers for insert to authenticated with check(seller_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='seller') and exists(select 1 from public.requests r where r.id=request_id and r.status='open' and r.buyer_id<>(select auth.uid())));
create policy "Seller updates own offer" on public.offers for update to authenticated using(seller_id=(select auth.uid()) and status='pending') with check(seller_id=(select auth.uid()));
create policy "Message participants read" on public.messages for select to authenticated using(sender_id=(select auth.uid()) or recipient_id=(select auth.uid()));
create policy "Sender creates message" on public.messages for insert to authenticated with check(sender_id=(select auth.uid()) and exists(select 1 from public.requests r where r.id=request_id and (r.buyer_id=(select auth.uid()) or exists(select 1 from public.offers o where o.request_id=r.id and o.seller_id=(select auth.uid())))));
create policy "Transaction participants read" on public.transactions for select to authenticated using(buyer_id=(select auth.uid()) or seller_id=(select auth.uid()));
create policy "Buyer accepts offer" on public.transactions for insert to authenticated with check(buyer_id=(select auth.uid()) and exists(select 1 from public.requests r where r.id=request_id and r.buyer_id=(select auth.uid())) and exists(select 1 from public.offers o where o.id=offer_id and o.request_id=request_id and o.seller_id=seller_id and o.status='pending'));
create policy "Transaction participants update" on public.transactions for update to authenticated using(buyer_id=(select auth.uid()) or seller_id=(select auth.uid())) with check(buyer_id=(select auth.uid()) or seller_id=(select auth.uid()));
create policy "Reviews public read" on public.reviews for select using(true);
create policy "Completed deal participants review" on public.reviews for insert to authenticated with check(reviewer_id=(select auth.uid()) and exists(select 1 from public.transactions t where t.id=transaction_id and t.status='completed' and (t.buyer_id=(select auth.uid()) or t.seller_id=(select auth.uid())) and reviewee_id in(t.buyer_id,t.seller_id) and reviewee_id<>(select auth.uid())));